def manualise_london_brief(apps, schema_editor):
    """Put the 2026-10-24 London brief into manual mode with no tips.

    Any tips the model had written for that service date are dropped so the
    card stays empty until the chef adds one. Other dates are left alone;
    the read path ignores rows that are not mode=manual.
    """
    CompanionBrief = apps.get_model("assist", "CompanionBrief")
    from datetime import date

    service_date = date(2026, 10, 24)
    payload = {"mode": "manual", "tips": []}
    row = CompanionBrief.objects.filter(service_date=service_date).first()
    if row is None:
        CompanionBrief.objects.create(
            service_date=service_date,
            payload=payload,
            model="",
        )
        return
    row.payload = payload
    row.model = ""
    row.save(update_fields=["payload", "model", "updated_at"])


